import{bank,findAnswer,pickRound}from './bank.js';
const $=id=>document.getElementById(id);let questions=[],index=0,records=[],locked=false;
function start(){questions=pickRound();index=0;records=[];locked=false;$('results').hidden=true;$('play').hidden=false;render()}
function render(){locked=false;const q=questions[index];$('round').textContent=`第 ${String(index+1).padStart(2,'0')} / 07 题`;$('total').textContent=records.reduce((s,r)=>s+r.score,0);$('progress').innerHTML=questions.map((_,i)=>`<span class="${i<index?'done':i===index?'current':''}" aria-label="第 ${i+1} 题"></span>`).join('');$('category').textContent=q.category;$('question').textContent=q.title;$('hint').textContent=q.hint;$('answer').value='';$('answer').disabled=false;$('submit').disabled=false;$('skip').hidden=false;$('feedback').replaceChildren();if(index>0)$('answer').focus()}
function submit(value){if(typeof value!=='string'||value.length>60)return{error:'请输入 60 字以内的文本'};if(locked)return{error:'本题已经完成'};const q=questions[index],match=findAnswer(q,value);if(!match){$('feedback').innerHTML='<p class="error">题库暂未识别这个答案。请检查拼写、换个名称，或尝试其他答案；本次不扣分。</p>';return{recognized:false}}finish(match);return{recognized:true,answer:match.name,score:match.score}}
function finish(match){if(locked)return;locked=true;const q=questions[index];records.push({question:q.title,answer:match?.name??'跳过',score:match?.score??0});$('total').textContent=records.reduce((s,r)=>s+r.score,0);$('answer').disabled=true;$('submit').disabled=true;$('skip').hidden=true;const score=match?.score??0;const feedback=$('feedback');feedback.className='feedback';feedback.innerHTML=`<div class="scoreline"><div><div class="category">${match?(score>=75?'深海发现':score>=40?'另辟蹊径':'正确，继续探索'):'这一题，留待下次'}</div><h2>${match?match.name:'已跳过'}</h2></div><div class="score">+${score}<small>分</small></div></div><div class="meter"><div style="width:${score}%"></div></div><p>冷门度为题库预设分值，不代表真实玩家统计。看看本题的其他答案：</p><div class="examples"></div><button class="primary" id="next">${index===6?'查看本轮成绩':'继续下潜 →'}</button>`;[...q.answers].sort((a,b)=>b.score-a.score).slice(0,4).forEach(a=>{const el=document.createElement('span');el.textContent=`${a.name} · ${a.score} 分`;feedback.querySelector('.examples').append(el)});$('next').onclick=next;$('next').focus()}
function next(){if(!locked)return;if(index<6){index++;render()}else{showResults()}}
function showResults(){$('play').hidden=true;$('results').hidden=false;$('round').textContent='本轮下潜完成';$('progress').querySelectorAll('span').forEach(s=>s.className='done');const total=records.reduce((s,r)=>s+r.score,0);$('results').innerHTML=`<div class="category">DIVE COMPLETE · ${records.filter(r=>r.score>0).length} / 7 题已答对</div><h2>${total>=500?'你找到了深海宝藏。':total>=300?'你有自己的思考航线。':'海很大，继续探索。'}</h2><div class="resultscore">${total}<small> / 700 分</small></div><div id="recap"></div><button class="primary" id="again">再潜一轮 ↻</button><p class="hint" style="text-align:center;margin:14px 0 0">免费无限玩 · 每轮重新随机抽题</p>`;records.forEach((r,i)=>{const row=document.createElement('div');row.className='resultrow';const label=document.createElement('span');label.textContent=`${i+1}. ${r.question} ${r.answer}`;const points=document.createElement('b');points.textContent=`${r.score} 分`;row.append(label,points);$('recap').append(row)});$('again').onclick=start;$('again').focus()}
$('form').onsubmit=e=>{e.preventDefault();submit($('answer').value)};$('skip').onclick=()=>finish(null);$('help').onclick=()=>$('rules').showModal();$('close').onclick=$('gotit').onclick=()=>$('rules').close();$('rules').onclick=e=>{if(e.target===$('rules')){const r=$('rules').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('rules').close()}};
start();
// Optional WebMCP integration; the same validation and round state back both UI and tool calls.
const context=document.modelContext??navigator.modelContext; if(context?.registerTool){try{context.registerTool({name:'get_game_state',annotations:{readOnlyHint:true},description:'Get current Deepcut question and round score.',inputSchema:{type:'object',properties:{}},execute:async()=>({content:[{type:'text',text:JSON.stringify({question:$('play').hidden?null:questions[index].title,round:index+1,answered:locked,records})}]})});context.registerTool({name:'submit_answer',annotations:{readOnlyHint:false},description:'Submit one answer for the current question. Chinese and English aliases are accepted.',inputSchema:{type:'object',properties:{answer:{type:'string'}},required:['answer']},execute:async({answer})=>({content:[{type:'text',text:JSON.stringify(submit(answer))}]})})}catch(error){console.warn("WebMCP registration unavailable",error)}}